import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Performance Meeting 2023-02-09","description":"","frontmatter":{"title":"Ceph Performance Meeting 2023-02-09","date":"2023-02-09T00:00:00.000Z","updated":"2023-02-15T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","代码审查","集群配置"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Performance_Meeting_2023-02-09.md","filePath":"posts/2023/Ceph_Performance_Meeting_2023-02-09.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_Performance_Meeting_2023-02-09.md"};function o(n,e,s,c,h,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph存储系统更新与优化</strong></p><ul><li>讨论了新的分配器格式版本2 (allocator format version 2) 的实现与性能改进。</li><li>探讨了混合分配器（Hybrid allocator）的工作原理及可能的改进方向。</li></ul></li><li><p><strong>性能优化与测试</strong></p><ul><li>讨论了通过改进分配器格式减少磁盘空间使用和提高性能的方法。</li><li>提到了单元测试结果，显示新方法在特定条件下性能优于旧方法。</li></ul></li><li><p><strong>代码审查与合并</strong></p><ul><li>讨论了多个Pull Request（PR）的审查状态和合并计划，包括避免使用整个空间迭代器的PR。</li><li>讨论了禁用QAT（Quick Assist Technology）忙轮询的简单PR，考虑其合并的可能性。</li></ul></li><li><p><strong>集群性能和配置更新</strong></p><ul><li>分享了Corey和David Orman的集群在应用优化后的良好表现。</li><li>讨论了RocksDB调优和BlueFS增量日志更新的效果。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>计划合并几个PR，特别是那些经过审查并显示性能改进的PR。</li><li>决定继续测试和评估RocksDB的新调优设置，以确定其在生产环境中的效果。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续进行代码审查和测试，确保所有PR都符合性能和稳定性的要求。</li><li>进一步探索和评估RocksDB调优和BlueFS更新的长期影响。</li><li>计划在未来的会议中继续讨论和更新这些议题的进展。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了QAT技术的测试和集成问题，以及可能的解决方案。</li><li>提到了关于集群升级和配置更新的策略，特别是在即将到来的Reef版本中。</li></ul><p>会议结束时，所有参与者对当前的进展表示满意，并期待在下一会议中继续讨论和解决问题。</p>',10)])])}const _=l(r,[["render",o]]);export{d as __pageData,_ as default};
